    """Score one candidate stack for the container being relocated. Lowest score wins."""
    priority = 0.0

    # First priority: check if the stack is safe (DIFF > 0)
    if DIFF > 0:
        # If stack is safe, prioritize stacks with more flexibility (EMP), lower average ID, and less blocking
