        else:
            priority = 3.0
    else:
        # Stack is not safe; prioritize based on future blocking potential
        if RI == 0:
            priority = 4.0
        elif RI == 1:
            priority = 5.0
        else:
            priority = 6.0

    # Second priority: adjust based on average ID compared to CUR
    if AVG < CUR:
        priority -= 1.0
    elif AVG > CUR:
        priority += 1.0

    # Third priority: adjust based on stack height (SH)
